/**
 * Service worker — the app shell, offline.
 *
 * Hand-written rather than generated by Workbox. The routing below is about
 * forty lines of logic, and vite-plugin-pwa would add a build-time dependency
 * plus a precache manifest to keep in step, in exchange for solving a problem
 * this app does not have (dozens of route patterns). The tradeoff would flip
 * the moment code-splitting arrives.
 *
 * Two reasons this file is load-bearing rather than a nicety:
 *
 * 1. **Chrome will not offer to install the app without it** — a registered
 *    worker *with a fetch handler* is one of its two install criteria, the
 *    other being PNG icons at 192 and 512. No worker, no install prompt, and
 *    nothing in the console explaining the absence.
 * 2. **Installation is what protects the data on iOS.** Safari evicts
 *    script-writable storage after seven days without interaction, and
 *    home-screen-installed apps are exempt. So the worker is a precondition
 *    for the install that is a precondition for the storage that Stage 3's
 *    offline sync will live in.
 *
 * And the reason offline needs this *before* it needs a data layer: with no
 * signal you cannot fetch `index.html` from the TUF at all. The app fails to
 * start long before the question of stale data comes up.
 */

// Bump on any change to this file or to the precache list. The old cache is
// deleted on activate, so a stale asset cannot outlive its version.
const VERSION = "tw-v1";
const SHELL = `${VERSION}-shell`;

/**
 * Stable URLs worth having before the first offline launch.
 *
 * Hashed bundles are deliberately absent: their names are only known at build
 * time, and a hard-coded list would go stale silently — the worker would
 * install successfully, having cached nothing that exists. They are picked up
 * by the runtime rule below instead, which is correct because they are
 * immutable by content hash.
 */
const PRECACHE = [
  "/",
  "/manifest.webmanifest",
  "/icon.svg",
  "/icon-192.png",
  "/apple-touch-icon.png",
  "/fonts/bricolage-400-600.woff2",
  "/fonts/manrope-400-700.woff2",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL);
      // Individually, not addAll: addAll is atomic, so one 404 — a renamed
      // font, say — rejects the whole install and the app silently has no
      // worker at all. A missing font is worth less than an offline app.
      await Promise.all(
        PRECACHE.map((url) =>
          cache.add(new Request(url, { cache: "reload" })).catch(() => undefined),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => !n.startsWith(VERSION)).map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

/** Never cached, and never even wrapped. */
function isLive(url) {
  return (
    url.pathname.startsWith("/api/") ||
    url.pathname === "/healthz"
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Cross-origin: nothing here is ours to cache. Fonts are self-hosted and
  // there are no CDN requests by design, so this should never fire.
  if (url.origin !== self.location.origin) return;

  // ── Live data: do not intercept at all. ──
  // Returning early leaves the request to the browser, which matters more
  // than it looks for /api/stream: an SSE response is an infinite body, and
  // passing one through respondWith() holds the stream inside the worker
  // where it can be buffered or torn down on worker restart. The live
  // dashboard would then stop updating with no error anywhere.
  //
  // Caching any /api/ GET would be worse than useless — a cached /api/state
  // is a screenshot of a training run presented as the current one, which is
  // the "up but lying" failure this project keeps trying to eliminate.
  if (isLive(url)) return;

  // ── Navigation: network first, cache as the fallback. ──
  // Deliberately NOT cache-first, despite the shell being cacheable. Deploys
  // here are "npm run build, copy to the TUF, every device has it on next
  // load", and cache-first HTML would break exactly that: the page would keep
  // serving yesterday's shell until a worker update happened to land. Network
  // first keeps deploys instant; the cache fallback is what makes the app
  // launch with the tailnet unreachable, which is the actual requirement.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(SHELL);
          // Store under "/" rather than the request URL. The app is a single
          // shell and the URL may carry a query; keying on the full URL would
          // fill the cache with near-identical copies and still miss on the
          // one path that matters.
          cache.put("/", fresh.clone());
          return fresh;
        } catch {
          const cached = await caches.match("/");
          if (cached) return cached;
          // No shell cached yet — this device has never been online here.
          // Say so plainly instead of letting the browser show its own
          // "cannot connect" page, which reads like the app is broken.
          return new Response(
            "<!doctype html><meta charset=utf-8><title>trainwatch</title>" +
              "<style>body{background:#04070a;color:#8ea3a3;font:14px/1.6 system-ui;" +
              "display:grid;place-items:center;height:100vh;margin:0;text-align:center;padding:2rem}" +
              "code{color:#31d0c6}</style>" +
              "<div><p>Offline, and this device has no cached copy yet.</p>" +
              "<p>Open trainwatch once while the tailnet is reachable, then " +
              "add it to your home screen.</p></div>",
            { status: 503, headers: { "Content-Type": "text/html; charset=utf-8" } },
          );
        }
      })(),
    );
    return;
  }

  // ── Everything else: cache first. ──
  // Safe because it is all content-addressed or effectively static — hashed
  // bundles under /assets/, woff2 fonts, icons, the manifest. A hashed asset
  // can be cached forever precisely because a change produces a new name.
  event.respondWith(
    (async () => {
      const cached = await caches.match(request);
      if (cached) return cached;
      try {
        const fresh = await fetch(request);
        // Only 200s. Caching an opaque or error response means a transient
        // 502 during a deploy gets pinned into the cache and served happily
        // for the lifetime of the version.
        if (fresh.ok && fresh.status === 200) {
          const cache = await caches.open(SHELL);
          cache.put(request, fresh.clone());
        }
        return fresh;
      } catch (err) {
        // Let the caller see a real failure rather than a synthesised 200.
        throw err;
      }
    })(),
  );
});
